pub mod http {
    //! What a flow returns to pick the status of an HTTP answer:
    //! `return Err(eda_runtime::http::HttpError::not_found("no such order").into());`
    //! Any other error is an internal error (500) whose details are only logged, and so is the message of a 5xx.

    #[derive(Debug)]
    pub struct HttpError {
        pub status: u16,
        pub message: String,
        /// Seconds for the `Retry-After` header (429 and 503).
        pub retry_after: Option<u64>,
    }

    impl HttpError {
        pub fn new(status: u16, message: impl Into<String>) -> Self {
            Self {
                status,
                message: message.into(),
                retry_after: None,
            }
        }

        pub fn with_retry_after(mut self, seconds: u64) -> Self {
            self.retry_after = Some(seconds);
            self
        }

        pub fn bad_request(message: impl Into<String>) -> Self {
            Self::new(400, message)
        }

        pub fn unauthorized(message: impl Into<String>) -> Self {
            Self::new(401, message)
        }

        pub fn forbidden(message: impl Into<String>) -> Self {
            Self::new(403, message)
        }

        pub fn not_found(message: impl Into<String>) -> Self {
            Self::new(404, message)
        }

        pub fn conflict(message: impl Into<String>) -> Self {
            Self::new(409, message)
        }
    }

    impl std::fmt::Display for HttpError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{} {}", self.status, self.message)
        }
    }

    impl std::error::Error for HttpError {}

    /// `Set-Cookie`: safe by default (`HttpOnly`, `Secure`, `SameSite=Lax`, `Path=/`).
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct Cookie {
        pub name: String,
        pub value: String,
        pub max_age_secs: Option<u64>,
        pub path: String,
        pub http_only: bool,
        pub secure: bool,
        pub same_site: SameSite,
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum SameSite {
        Lax,
        Strict,
        None,
    }

    impl Cookie {
        pub fn new(name: impl Into<String>, value: impl Into<String>) -> Self {
            Self {
                name: name.into(),
                value: value.into(),
                max_age_secs: None,
                path: "/".to_string(),
                http_only: true,
                secure: true,
                same_site: SameSite::Lax,
            }
        }

        pub fn max_age(mut self, seconds: u64) -> Self {
            self.max_age_secs = Some(seconds);
            self
        }

        pub fn path(mut self, path: impl Into<String>) -> Self {
            self.path = path.into();
            self
        }

        pub fn http_only(mut self, yes: bool) -> Self {
            self.http_only = yes;
            self
        }

        pub fn secure(mut self, yes: bool) -> Self {
            self.secure = yes;
            self
        }

        pub fn same_site(mut self, same_site: SameSite) -> Self {
            self.same_site = same_site;
            self
        }

        /// The value of the `Set-Cookie` header. The cookie value is percent-encoded where needed, so that a
        /// `;` in it cannot add attributes of its own.
        pub fn header_value(&self) -> String {
            let mut out = format!("{}={}", self.name, encode_value(&self.value));
            if let Some(seconds) = self.max_age_secs {
                out.push_str(&format!("; Max-Age={seconds}"));
            }
            out.push_str(&format!("; Path={}", self.path));
            if self.http_only {
                out.push_str("; HttpOnly");
            }
            if self.secure {
                out.push_str("; Secure");
            }
            out.push_str(match self.same_site {
                SameSite::Lax => "; SameSite=Lax",
                SameSite::Strict => "; SameSite=Strict",
                SameSite::None => "; SameSite=None",
            });
            out
        }
    }

    /// The cookie-octets of RFC 6265, except `%`, which stands for an encoded byte.
    fn encode_value(value: &str) -> String {
        let mut out = String::with_capacity(value.len());
        for b in value.bytes() {
            let plain = matches!(b, 0x21 | 0x23..=0x24 | 0x26..=0x2B | 0x2D..=0x3A | 0x3C..=0x5B | 0x5D..=0x7E);
            if plain {
                out.push(b as char);
            } else {
                out.push_str(&format!("%{b:02X}"));
            }
        }
        out
    }

    /// The value of the cookie `name` among the `Cookie` headers of a request, decoded the way `Cookie` encodes it.
    /// The first cookie of that name wins (the browser sends the most specific path first); a value that does not
    /// decode to UTF-8 is as good as absent.
    pub fn cookie<'a>(headers: impl IntoIterator<Item = &'a str>, name: &str) -> Option<String> {
        headers
            .into_iter()
            .flat_map(|header| header.split(';'))
            .filter_map(|pair| pair.split_once('='))
            .find(|(n, _)| n.trim() == name)
            .and_then(|(_, value)| decode_value(value.trim().trim_matches('"')))
    }

    /// Undoes `encode_value`; a `%` that is not followed by two hex digits is kept as it is.
    fn decode_value(value: &str) -> Option<String> {
        let bytes = value.as_bytes();
        let mut out = Vec::with_capacity(bytes.len());
        let mut i = 0;
        while i < bytes.len() {
            let hex = (bytes[i] == b'%' && i + 2 < bytes.len())
                .then(|| std::str::from_utf8(&bytes[i + 1..i + 3]).ok())
                .flatten()
                .and_then(|h| u8::from_str_radix(h, 16).ok());
            match hex {
                Some(b) => {
                    out.push(b);
                    i += 3;
                }
                None => {
                    out.push(bytes[i]);
                    i += 1;
                }
            }
        }
        String::from_utf8(out).ok()
    }

    /// What a route answers when its `Respond` step sets a status or cookies: the body and the extras.
    #[derive(Debug)]
    pub struct Reply<T> {
        pub body: T,
        pub status: Option<u16>,
        pub cookies: Vec<Cookie>,
    }

    impl<T> Reply<T> {
        pub fn new(body: T) -> Self {
            Self {
                body,
                status: None,
                cookies: Vec::new(),
            }
        }

        pub fn status(mut self, status: u16) -> Self {
            self.status = Some(status);
            self
        }

        pub fn cookie(mut self, cookie: Cookie) -> Self {
            self.cookies.push(cookie);
            self
        }
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn a_session_cookie_is_safe_by_default() {
            let header = Cookie::new("session", "abc123").max_age(900).header_value();
            assert_eq!(header, "session=abc123; Max-Age=900; Path=/; HttpOnly; Secure; SameSite=Lax");
        }

        #[test]
        fn attributes_can_be_relaxed_one_by_one() {
            let header = Cookie::new("theme", "dark")
                .http_only(false)
                .secure(false)
                .same_site(SameSite::Strict)
                .path("/app")
                .header_value();
            assert_eq!(header, "theme=dark; Path=/app; SameSite=Strict");
            assert!(Cookie::new("a", "b").same_site(SameSite::None).header_value().ends_with("; Secure; SameSite=None"));
        }

        #[test]
        fn a_value_cannot_add_attributes() {
            let header = Cookie::new("x", "a; Domain=evil.example, b=c \"q\"\r\n é%").header_value();
            let value = header.split("; Path=").next().unwrap();
            assert!(!value.contains(';') && !value.contains(' ') && !value.contains('"') && !value.contains('\r'), "{value}");
            assert_eq!(value, "x=a%3B%20Domain=evil.example%2C%20b=c%20%22q%22%0D%0A%20%C3%A9%25");
        }

        #[test]
        fn a_cookie_is_read_back_as_it_was_set() {
            let sent = Cookie::new("session", "a; b=c é%").header_value();
            let pair = sent.split("; Path=").next().unwrap().to_string();
            assert_eq!(cookie([pair.as_str()], "session").as_deref(), Some("a; b=c é%"));
        }

        #[test]
        fn the_right_cookie_is_found_among_several() {
            let headers = ["theme=dark; session=first", "session=second"];
            assert_eq!(cookie(headers, "session").as_deref(), Some("first"));
            assert_eq!(cookie(headers, "theme").as_deref(), Some("dark"));
            assert_eq!(cookie(["xsession=no; session2=no"], "session"), None);
            assert_eq!(cookie(["session=\"quoted\""], "session").as_deref(), Some("quoted"));
            assert_eq!(cookie(["bare; session=ok"], "session").as_deref(), Some("ok"));
            assert_eq!(cookie([], "session"), None);
        }

        #[test]
        fn a_value_that_does_not_decode_is_absent() {
            assert_eq!(cookie(["a=%FF%FE"], "a"), None);
            // A stray `%` is kept.
            assert_eq!(cookie(["a=100%"], "a").as_deref(), Some("100%"));
            assert_eq!(cookie(["a=%zz"], "a").as_deref(), Some("%zz"));
        }

        #[test]
        fn a_reply_carries_status_and_cookies() {
            let reply = Reply::new("body").status(201).cookie(Cookie::new("a", "1")).cookie(Cookie::new("b", "2"));
            assert_eq!(reply.status, Some(201));
            assert_eq!(reply.cookies.len(), 2);
        }
    }
}

use std::future::Future;
use std::time::Duration;

use anyhow::{Context, Result, bail};
use rdkafka::admin::{AdminClient, AdminOptions, NewTopic, TopicReplication};
use rdkafka::client::DefaultClientContext;
use rdkafka::config::ClientConfig;
use rdkafka::consumer::{CommitMode, Consumer, StreamConsumer};
use rdkafka::message::{Header, Message as _, OwnedHeaders};
use rdkafka::producer::{FutureProducer, FutureRecord};
use rdkafka::types::RDKafkaErrorCode;

/// Attempts a handler gets before the record is parked on the dead-letter topic.
const MAX_ATTEMPTS: u32 = 3;

pub fn init_tracing() {
    use tracing_subscriber::EnvFilter;
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    tracing_subscriber::fmt().with_env_filter(filter).init();
}

pub fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Random UUID v4 as a string, handy for generating identifiers in flows.
pub fn new_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

pub struct TopicSpec {
    pub name: String,
    pub partitions: i32,
    pub replication: i32,
}

/// Creates the topics that do not exist yet. Retries while the broker is starting up.
pub async fn ensure_topics(brokers: &str, specs: &[TopicSpec]) -> Result<()> {
    let admin: AdminClient<DefaultClientContext> = ClientConfig::new()
        .set("bootstrap.servers", brokers)
        .create()
        .context("cannot create Kafka admin client")?;
    let topics: Vec<NewTopic<'_>> = specs
        .iter()
        .map(|s| NewTopic::new(&s.name, s.partitions, TopicReplication::Fixed(s.replication)))
        .collect();

    let mut attempt = 0;
    loop {
        attempt += 1;
        match admin.create_topics(&topics, &AdminOptions::new()).await {
            Ok(results) => {
                for result in results {
                    match result {
                        Ok(name) => tracing::info!("created topic {name}"),
                        Err((_, RDKafkaErrorCode::TopicAlreadyExists)) => {}
                        Err((name, code)) => bail!("cannot create topic {name}: {code}"),
                    }
                }
                return Ok(());
            }
            Err(e) if attempt < 10 => {
                tracing::warn!("Kafka not ready at {brokers} ({e}), retrying");
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
            Err(e) => return Err(e).context(format!("Kafka unreachable at {brokers}")),
        }
    }
}

pub struct Producer {
    inner: FutureProducer,
}

impl Producer {
    pub fn new(brokers: &str) -> Result<Self> {
        let inner: FutureProducer = ClientConfig::new()
            .set("bootstrap.servers", brokers)
            .set("enable.idempotence", "true")
            .set("message.timeout.ms", "10000")
            .create()
            .context("cannot create Kafka producer")?;
        Ok(Self { inner })
    }

    /// Encodes `message` as protobuf and publishes it. Records with the same key land on
    /// the same partition and are therefore consumed in order.
    pub async fn publish<M: prost::Message>(
        &self,
        topic: &str,
        key: Option<&str>,
        message: &M,
    ) -> Result<()> {
        self.publish_bytes(topic, key.map(str::as_bytes), &message.encode_to_vec())
            .await
    }

    pub async fn publish_bytes(
        &self,
        topic: &str,
        key: Option<&[u8]>,
        payload: &[u8],
    ) -> Result<()> {
        self.publish_bytes_with_headers(topic, key, payload, &[]).await
    }

    /// Like [`Producer::publish_bytes`], with string headers (the dead-letter records carry the
    /// reason they were parked).
    pub async fn publish_bytes_with_headers(
        &self,
        topic: &str,
        key: Option<&[u8]>,
        payload: &[u8],
        headers: &[(&str, &str)],
    ) -> Result<()> {
        let mut record: FutureRecord<'_, [u8], [u8]> = FutureRecord::to(topic).payload(payload);
        if let Some(key) = key {
            record = record.key(key);
        }
        if !headers.is_empty() {
            record = record.headers(headers.iter().fold(OwnedHeaders::new(), |h, (key, value)| {
                h.insert(Header {
                    key,
                    value: Some(*value),
                })
            }));
        }
        self.inner
            .send(record, Duration::from_secs(5))
            .await
            .map_err(|(e, _)| anyhow::anyhow!("publish to {topic} failed: {e}"))?;
        Ok(())
    }
}

/// Consumes `topic` forever, decoding each record as `M` and calling `handler`.
///
/// Delivery is at-least-once: the offset is committed after the handler succeeded, or
/// after the record was parked on `<topic>.dlq` once `MAX_ATTEMPTS` attempts failed
/// (or when it cannot be decoded). If the dead-letter publish itself fails it is retried
/// until it succeeds. Make handlers idempotent.
pub async fn consume<M, F, Fut>(
    brokers: &str,
    group_id: &str,
    topic: &str,
    handler: F,
) -> Result<()>
where
    M: prost::Message + Default + Clone,
    F: Fn(M) -> Fut,
    Fut: Future<Output = Result<()>>,
{
    let consumer: StreamConsumer = ClientConfig::new()
        .set("bootstrap.servers", brokers)
        .set("group.id", group_id)
        .set("enable.auto.commit", "false")
        .set("auto.offset.reset", "earliest")
        .create()
        .context("cannot create Kafka consumer")?;
    consumer.subscribe(&[topic])?;
    let dlq = Producer::new(brokers)?;
    let dlq_topic = format!("{topic}.dlq");
    tracing::info!("consuming {topic} as group {group_id}");

    loop {
        let record = match consumer.recv().await {
            Ok(record) => record,
            Err(e) => {
                tracing::error!("Kafka error on {topic}: {e}");
                tokio::time::sleep(Duration::from_secs(1)).await;
                continue;
            }
        };
        let payload = record.payload().unwrap_or_default();

        let outcome = match M::decode(payload) {
            Err(e) => Err(anyhow::anyhow!("cannot decode record: {e}")),
            Ok(event) => run_with_retries(&handler, event).await,
        };
        if let Err(e) = outcome {
            tracing::error!(
                "giving up on record {topic}[{}]@{}: {e:#}; parking it on {dlq_topic}",
                record.partition(),
                record.offset()
            );
            // Never drop a record silently: keep trying until the dead-letter topic accepts it.
            // This blocks the partition, which is the safe choice for at-least-once delivery.
            while let Err(e) = dlq.publish_bytes(&dlq_topic, record.key(), payload).await {
                tracing::error!("cannot publish to {dlq_topic}: {e:#}; retrying");
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
        }
        // A failed commit only means the record may be redelivered, which at-least-once allows.
        if let Err(e) = consumer.commit_message(&record, CommitMode::Async) {
            tracing::warn!("cannot commit offset on {topic}: {e}");
        }
    }
}

async fn run_with_retries<M, F, Fut>(handler: &F, event: M) -> Result<()>
where
    M: Clone,
    F: Fn(M) -> Fut,
    Fut: Future<Output = Result<()>>,
{
    let mut attempt = 1;
    loop {
        match handler(event.clone()).await {
            Ok(()) => return Ok(()),
            Err(e) if attempt < MAX_ATTEMPTS => {
                tracing::warn!("handler failed (attempt {attempt}/{MAX_ATTEMPTS}): {e:#}");
                tokio::time::sleep(Duration::from_millis(250 * 2u64.pow(attempt))).await;
                attempt += 1;
            }
            Err(e) => return Err(e),
        }
    }
}
